    [Fact]
    public void MiiStudioConversion_IsCorrect()
    {
        foreach (var kvp in MiiB64ToStudioResponse)
        {
            var miiBytes = Convert.FromBase64String(kvp.Key);
            var gen1Wii = new Gen1Wii(new KaitaiStream(miiBytes));
            var miiHex = MiiService.CreateStudioMii(gen1Wii);

            miiHex.ShouldBeEquivalentTo(kvp.Value);
        }
    }
}
